veVaultIndex));\n  }, [activeVaultIndex, vaults]);\n\n  // 监听管理仓库窗口的变更事件（实时同步）\n  useEffect(() => {\n    const unlisten = listen<{ vaults: VaultInfo[]; activeIndex: number }>(\"vaults-changed\", (event) => {\n      setVaults(event.payload.vaults);\n      setActiveVaultIndex(event.payload.activeIndex);\n    });\n    return () => { unlisten.then(fn => fn()); };\n  }, []);\n\n  // 根据 initialVaultPath 设置活动仓库\n  useEffect(() => {\n    if (initialVaultPath && vaults.length > 0) {\n      // 标准化路径：去除尾部斜杠，保证跨窗口路径比对可靠\n      const normalize = (p: string) => p.replace(/[\\\\/]+$/, \"\");\n      const target = normalize(initialVaultPath);\n      const index = vaults.findIndex(v => normalize(v.path) === target);\n      if (index >= 0 && index !== activeVaultIndex) {\n        setActiveVaultIndex(index);\n      }\n    }\n  }, [initialVaultPath, vaults]); // eslint-disable-line react-hooks/exhaustive-deps\n\n  // 路径式激活：临时仓库/欢迎仓库等异步注入场景下，先记下目标仓库路径，\n  // 等 vaults 更新到位后再按下标激活，避免与异步流程竞态导致激活错位\n  const [pendingActiveVaultPath, setPendingActiveVaultPath] = useState<string | null>(null);\n  useEffect(() => {\n    if (!pendingActiveVaultPath) return;\n    const index = vaults.findIndex((v) => {\n      const vp = v.path.replace(/[\\\\/]+$/, \"\");\n      return vp === pendingActiveVaultPath;\n    });\n    if (index >= 0 && index !== activeVaultIndex) {\n      setActiveVaultIndex(index);\n    }\n  }, [pendingActiveVaultPath, vaults, activeVaultIndex]);\n\n  // 兜底：仓库列表变化（如临时仓库被\"管理仓库\"同步事件覆盖）后活动下标越界 → 回到未选择\n  useEffect(() => {\n    if (activeVaultIndex >= vaults.length) {\n      setActiveVaultIndex(-1);\n    }\n  }, [vaults, activeVaultIndex]);\n\n  // ── 首次启动：物化并自动打开\"Tydora 介绍\"仓库 ──────────────────────\n  // 仅执行一次（localStorage 标记）；已有仓库的老用户只物化文档文件，不注入仓库。\n  // 文档语言跟随当前界面语言（首次启动时界面语言由操作系统语言自动检测决定，\n  // 见 i18n/detect.ts），用户仍可在设置中手动切换语言。\n  // settled：标记初始化流程结束（成功/失败/无需注入），无仓库自动弹管理仓库的\n  // 逻辑要等它完成，避免\"注入进行中\"时弹框抢先打开。\n  const [welcomeVaultSettled, setWelcomeVaultSettled] = useState<boolean>(\n    () => !!localStorage.getItem(WELCOME_VAULT_INITIALIZED_KEY),\n  );\n  useEffect(() => {\n    if (localStorage.getItem(WELCOME_VAULT_INITIALIZED_KEY)) return;\n    // 同步置标记：防 StrictMode 双跑与重复注入\n    localStorage.setItem(WELCOME_VAULT_INITIALIZED_KEY, \"1\");\n    let cancelled = false;\n    const finish = () => setWelcomeVaultSettled(true);\n    (async () => {\n      try {\n        const dir = await invoke<string>(\"ensure_welcome_vault\");\n        if (cancelled) { finish(); return; }\n        setWelcomeVaultDir(dir);\n        // 老用户（已有仓库）不做注入，仅在下次\"管理仓库\"里可以手动打开该目录\n        if (vaults.length > 0) { finish(); return; }\n        const lang = i18n.language?.startsWith(\"zh\") ? \"zh-CN\" : \"en-US\";\n        const vaultName = lang === \"zh-CN\" ? \"Tydora 介绍\" : \"Tydora Introduction\";\n        // 函数式更新：避免与临时仓库挂载（双击打开外部文件）等异步流程竞态时互相覆盖\n        setVaults((prev) => [...prev, { name: vaultName, path: dir }]);\n        setPendingActiveVaultPath(dir.replace(/[\\\\/]+$/, \"\"));\n        // 等仓库状态落地后再打开欢迎文档\n        const sep = navigator.platform?.toLowerCase().includes(\"win\") ? \"\\\\\" : \"/\";\n        const entry = lang === \"zh-CN\" ? \"欢迎.md\" : \"Welcome.md\";\n        setTimeout(() => {\n          void openFileRef.current(`${dir}${sep}${entry}`);\n        }, 400);\n      } catch (e) {\n        console.error(\"初始化介绍仓库失败\", e);\n      } finally {\n        finish();\n      }\n    })();\n    return () => { cancelled = true; };\n  }, []); // eslint-disable-line react-hooks/exhaustive-deps\n\n  // 启动时窗口可见性策略（秒开版）：\n  // - 目标：用户点击 exe → 尽可能早看到主窗口（Rust 端 visible=true 已保证创建即显示）\n  // - 正常路径（有仓库 / 双击 .md 打开文件）：始终显示主窗口，不做跨窗口跳转\n  // - 无仓库且无外部文件：先立即显示主窗口（不阻塞），等 pending files 两次拉取结束后\n  //   再异步打开\"管理仓库\"窗口并隐藏/关闭主窗口，保证\"用户始终能看到界面\"\n  //\n  // 关键点：这里**不再依赖 externalLaunchSettled 作为前置条件**（否则被迫等 1.2s 的兜底二次拉取），\n  // 而是\"先显示再说\"——外部文件即便稍后到达也有事件监听 + useLayoutEffect 响应。\n  useEffect(() => {\n    const win = getCurrentWindow();\n    // 1) Rust 端 setup 已经调用了 window.show()（正确尺