e */ }\n        openSettings(item.tab);\n      },\n    })),\n  ], [t, handleSave, activeVaultIndex, fileName, handleNewWindow, handleSidebarToggle, cycleMode, toggleTypewriterMode, handleMinimize, handleToggleMaximize, handleClose, setViewMode, setActiveMode, viewMode, vaults, handleCopyAsMarkdown, content, getGraphSettings, handleOpenXhs, handlePublish, openSettings, guardSourceModeCommand]);\n\n  return (\n    <div className=\"app\">\n      {/* 主内容区：左侧栏 + 编辑区域 */}\n      <div className=\"main-container\">\n        {/* 左侧栏 */}\n        <VimSidebar\n          vaults={vaults}\n          activeVaultIndex={activeVaultIndex}\n          currentFilePath={fileName}\n          content={content}\n          onSelectFile={handleSelectFile}\n          onSelectHeading={handleSelectHeading}\n          onRemoveVault={handleRemoveVault}\n          onNewWindow={handleNewWindow}\n          onOpenInNewPanel={handleOpenInNewPanel}\n          canOpenInNewPanel={!!fileName && isCurrentFileMarkdown && !canvasFilePath && !previewFilePath && !graphViewOpen}\n          onOpenNewVault={handleOpenNewVault}\n          onSelectVault={setActiveVaultIndex}\n          collapsed={!sidebarOpen}\n          refreshKey={treeRefreshKey}\n          graphRefreshKey={graphRefreshKey}\n          width={sidebarWidth}\n          onWidthChange={setSidebarWidth}\n          onBookmark={handleShowBookmarkDialog}\n          outlineTrigger={outlineTrigger}\n          side=\"left\"\n          tabs={leftTabs}\n          showFileIcons={showFileIcons}\n          onMoveTabToSide={moveSidebarTab}\n          onOpenGlobalGraph={() => setGraphViewOpen((prev) => !prev)}\n          graphViewOpen={graphViewOpen}\n          onManageVaults={() => setVaultManagerOpen(true)}\n          onOpenSettings={() => openSettings()}\n        />\n\n        {/* 编辑区域 */}\n        <main className={`editor-container${!sidebarOpen ? \" sidebar-is-closed\" : \"\"}${(autoHideTopbar || (!sidebarOpen && autoHideTopbarOnCollapse)) ? \" sidebar-collapse